'use strict';
const fs = require('fs'), Module = require('module'), { performance } = require('perf_hooks');
const root = '/home/tim/repos/bts';
const old = new Module(root + '/bts/selection-before.js');
old.filename = root + '/bts/selection-before.js'; old.paths = Module._nodeModulePaths(root + '/bts');
old._compile(fs.readFileSync('/tmp/bts-selection-before.js', 'utf8'), old.filename);
const current = require(root + '/bts/match_automation');
const { response } = require(root + '/debug/queue_responsiveness/fixture');
const state = require(root + '/bts/btp_parse').get_btp_state(response());
const matches = state.matches.map((m, i) => ({ _id: 'm' + i, score_status: 'normal', btp_match_ids: [{ planning: m.PlanningID[0] }], setup: {
  state: 'scheduled', is_match: true, match_num: m.MatchNr[0], event_name: 'Singles',
  teams: m.bts_players.map(team => ({ players: team.map(p => ({ btp_id: p.ID[0] })) })),
} }));
const courts = Array.from({length: 13}, (_, i) => ({_id: 'c' + i, is_active: true}));
const tournament = { matches, courts, official_rotation_mode: 'disabled', call_on_court_participant_readiness_mode: 'disabled' };
function run(automation, fields) {
  if (automation.calculate_call_on_court_selection) return automation.calculate_call_on_court_selection(tournament, fields, {now_ts: 1});
  const potential_matches = automation.find_field_independent_call_on_court_candidates(tournament, {now_ts: 1});
  return {potential_matches, by_court: new Map(fields.map(c => [c._id, automation.find_call_on_court_candidates(tournament, c._id, { now_ts: 1, candidate_matches: potential_matches })]))};
}
for (const field_count of [1, 13]) {
 for (const [name, automation] of [['before', old.exports], ['current', current]]) {
  const timings = []; let result;
  for (let i = 0; i < 5; i++) { const start = performance.now(); result = run(automation, courts.slice(0, field_count)); timings.push(performance.now() - start); }
  console.log(JSON.stringify({ name, field_count, ms: timings, potential: result.potential_matches.length, per_court: [...result.by_court.values()].map(a => a.length) }));
 }
}
